sctp_disposition_t sctp_process_oob_chunk(struct net *net,
                                          const struct sctp_endpoint *ep,
                                          const struct sctp_association *asoc,
                                          sctp_subtype_t type,
                                          void *arg,
                                          sctp_cmd_seq_t *commands)
{
    sctp_chunk_t *chunk = arg;
    sctp_disposition_t disposition = SCTP_DISPOSITION_CONSUME;

    if (!chunk)
        return SCTP_DISPOSITION_DISCARD;

    net->sctp.sctpSndDupChunks++;

    if (chunk->chunk_hdr->type == SCTP_CID_SHUTDOWN_ACK) {
        sctp_add_cmd(commands, SCTP_CMD_NEW_ASOC, asoc);
        disposition = SCTP_DISPOSITION_ABORT;
    } else if (chunk->chunk_hdr->type == SCTP_CID_ABORT) {
        sctp_add_cmd(commands, SCTP_CMD_DELETE_TCB, asoc);
        disposition = SCTP_DISPOSITION_ABORT;
    } else if (chunk->chunk_hdr->type == SCTP_CID_COOKIE_ACK) {
        sctp_add_cmd(commands, SCTP_CMD_COOKIE_ACK, chunk);
        disposition = SCTP_DISPOSITION_DISCARD;
    } else {
        disposition = SCTP_DISPOSITION_CONSUME;
    }

    return disposition;
}

sctp_disposition_t sctp_process_out_of_band_chunk(struct net *net,
                                                  const struct sctp_endpoint *ep,
                                                  const struct sctp_association *asoc,
                                                  sctp_subtype_t type,
                                                  void *arg,
                                                  sctp_cmd_seq_t *commands)
{
    sctp_chunk_t *chunk = (sctp_chunk_t *)arg;
    sctp_disposition_t disposition = SCTP_DISPOSITION_CONSUME;

    /* Increment appropriate SCTP statistics for processing out-of-band chunks */
    net->sctp.statistics.incoming_chunks[type];

    /* Validate the chunk length */
    if (chunk->length < sizeof(sctp_chunk_t)) {
        disposition = SCTP_DISPOSITION_DISCARD;
        goto out;
    }

    /* Handle SHUTDOWN_ACK chunk */
    if (SCTP_CHUNK_IS(type, SHUTDOWN_ACK)) {
        sctp_cmd_seq_init(commands);
        sctp_cmd_sf(commands, SCTP_CMD_REPLY, SCTP_NULL());
        sctp_cmd_sf(commands, SCTP_CMD_UPDATE_TSN, SCTP_NULL());
    }

    /* Handle ABORT chunk */
    if (SCTP_CHUNK_IS(type, ABORT)) {
        sctp_cmd_seq_init(commands);
        sctp_cmd_sf(commands, SCTP_CMD_ABORT, SCTP_NULL());
        disposition = SCTP_DISPOSITION_ABORT;
        goto out;
    }

    /* Handle COOKIE_ACK chunk */
    if (SCTP_CHUNK_IS(type, COOKIE_ACK)) {
        sctp_cmd_seq_init(commands);
        sctp_cmd_sf(commands, SCTP_CMD_COOKIE_ACK, SCTP_NULL());
        disposition = SCTP_DISPOSITION_ACK;
        goto out;
    }

    /* Discard packet if it does not match any specific chunk type handling */
    disposition = SCTP_DISPOSITION_DISCARD;

out:
    return disposition;
}

sctp_disposition_t sctp_process_oob_chunk(struct net *net,
                                          const struct sctp_endpoint *ep,
                                          const struct sctp_association *asoc,
                                          sctp_subtype_t type,
                                          void *arg,
                                          sctp_cmd_seq_t *commands)
{
    sctp_chunk_t *chunk = arg;
    sctp_disposition_t disposition = SCTP_DISPOSITION_CONSUME;

    /* Increment SCTP statistics for processing out-of-band chunk */
    NET_INC_STATS(net, SCTP_MIB_IN_PKT);

    /* Validate chunk length */
    if (chunk->chunk_hdr->length < sizeof(sctp_chunkhdr_t)) {
        NET_INC_STATS(net, SCTP_MIB_IN_PKT_TOOBIG);
        return SCTP_DISPOSITION_DISCARD;
    }

    /* Handle specific chunk types */
    switch (chunk->chunk_hdr->type) {
    case SCTP_CID_SHUTDOWN_ACK:
        if (asoc && asoc->state == SCTP_STATE_SHUTDOWN_PENDING) {
            sctp_cmd_seq_push(commands, SCTP_CMD_SET_TCUACK);
            sctp_cmd_seq_push(commands, SCTP_CMD_REPLY);
        }
        break;

    case SCTP_CID_ABORT:
        disposition = SCTP_DISPOSITION_ABORT;
        break;

    case SCTP_CID_COOKIE_ACK:
        if (asoc && asoc->state == SCTP_STATE_COOKIE_ECHOED) {
            sctp_cmd_seq_push(commands, SCTP_CMD_T3_RTX_TIMERS_STOP);
            sctp_cmd_seq_push(commands, SCTP_CMD_HB_TIMER_STOP);
            sctp_cmd_seq_push(commands, SCTP_CMD_COOKIE_ACK_RECEIVED);
        }
        break;

    default:
        /* Discard unknown or irrelevant chunks */
        disposition = SCTP_DISPOSITION_DISCARD;
        break;
    }

    return disposition;
}

sctp_disposition_t sctp_process_out_of_band_chunk(struct net *net,
                                                  const struct sctp_endpoint *ep,
                                                  const struct sctp_association *asoc,
                                                  sctp_subtype_t type,
                                                  void *arg,
                                                  sctp_cmd_seq_t *commands)
{
    struct sctp_chunk *chunk = arg;
    sctp_disposition_t disposition = SCTP_DISPOSITION_CONSUME;

    /* Increment SCTP statistics for processing out-of-band chunks */
    SCTP_INC_STATS(net, SCTP_MIB_OUTOFBANDCHUNKS);

    /* Validate chunk length */
    if (chunk->chunk_len < sizeof(struct sctp_chunk)) {
        return SCTP_DISPOSITION_BAD;
    }

    /* Handle specific chunk types */
    switch (type) {
        case SCTP_SUBTYPE_SHUTDOWN_ACK:
            sctp_cmd_seq_append(commands, SCTP_CMD_SHUTDOWN_ACK_RECEIVED);
            break;

        case SCTP_SUBTYPE_ABORT:
            sctp_cmd_seq_append(commands, SCTP_CMD_ABORT_ASSOCIATION);
            disposition = SCTP_DISPOSITION_ABORT;
            break;

        case SCTP_SUBTYPE_COOKIE_ACK:
            sctp_cmd_seq_append(commands, SCTP_CMD_COOKIE_ACK_RECEIVED);
            break;

        default:
            disposition = SCTP_DISPOSITION_DISCARD;
            break;
    }

    return disposition;
}

sctp_disposition_t sctp_process_oob_chunk(struct net *net,
                                          const struct sctp_endpoint *ep,
                                          const struct sctp_association *asoc,
                                          sctp_subtype_t type,
                                          void *arg,
                                          sctp_cmd_seq_t *commands)
{
    sctp_disposition_t disposition = SCTP_DISPOSITION_CONSUME;
    struct sctp_chunk *chunk = arg;

    /* Increment SCTP statistics for out-of-band chunk processing */
    __sctp_stat_inc(net, SCTP_MIB_OUTOFBANDCHUNKS);

    /* Validate chunk length */
    if (!sctp_chunk_len_valid(chunk)) {
        disposition = SCTP_DISPOSITION_DISCARD;
        return disposition;
    }

    /* Handle specific chunk types */
    if (type.chunk == SCTP_SHUTDOWN_ACK) {
        sctp_add_cmd(commands, SCTP_CMD_SHUTDOWN_ACK);
    } else if (type.chunk == SCTP_ABORT) {
        sctp_add_cmd(commands, SCTP_CMD_ABORT);
        disposition = SCTP_DISPOSITION_DISCARD;
    } else if (type.chunk == SCTP_COOKIE_ACK) {
        sctp_add_cmd(commands, SCTP_CMD_COOKIE_ACK);
        disposition = SCTP_DISPOSITION_CONSUME;
    } else {
        /* Unknown or non-actionable chunk type */
        disposition = SCTP_DISPOSITION_DISCARD;
    }

    return disposition;
}
